  // ── sign-in · home · composer · agent integration ───────────────────
  'Claude Code, Codex 같은 코딩 에이전트를 이 인스턴스에 연결합니다. 발급받은 키로 인증하며, 사용량과 한도는 그 키를 따라갑니다.': 'Connect coding agents such as Claude Code or Codex to this instance. They authenticate with a key you issue, and usage and limits follow that key.',
  '먼저 키를 발급하세요': 'Issue a key first',
  '발급 직후 한 번만 보이고 다시 확인할 수 없습니다.': 'It is shown once at creation and cannot be read again.',
  'API 키 발급': 'Issue API key',
  '모델 선택': 'Model',
  '고른 모델의 이름이 아래 설정에 그대로 들어갑니다.': 'The model you pick goes straight into the settings below.',
  '사용 가능한 모델 없음': 'No models available',
  'Agent 기본 모델': 'Agent default model',
  'Anthropic 형식으로 주고받습니다.': 'Speaks the Anthropic format.',
  '이 터미널 창에서만 유효합니다. 영구 적용은 ~/.bashrc 나 ~/.zshrc 에 넣으세요.':
    'Applies to this terminal only. To keep it, add it to ~/.bashrc or ~/.zshrc.',
  'PowerShell 기준입니다. 이 창에서만 유효하며, cmd.exe 에서는 set 이름=값 을 씁니다.':
    'PowerShell syntax. Applies to this window only; in cmd.exe use set NAME=value.',
  'PowerShell 에서는 curl 이 Invoke-WebRequest 의 별칭이라 curl.exe 로 부릅니다.':
    'In PowerShell, curl is an alias of Invoke-WebRequest, so call curl.exe.',
  'OpenAI 형식으로 주고받습니다. 주소 끝에 /v1 이 붙는 것에 주의하세요.': 'Speaks the OpenAI format. Note the /v1 at the end of the address.',
  '이 키로 쓴 양은 사용량 화면의 API 키 항목에 따로 집계됩니다.': 'What this key spends is counted separately under API keys on the usage screen.',
  '월 한도는 계정에 걸려 있습니다. 키를 여러 개 만들어도 한도가 늘지 않고, 다 쓰면 요청이 거부됩니다.':
    'The monthly limit sits on the account. Extra keys do not raise it, and requests are refused once it is spent.',
  '키를 폐기하면 즉시 막힙니다. 도구 쪽 설정도 함께 지우세요.': 'Revoking a key blocks it immediately — clear it from the tool as well.',
  '대화에서 끝나지 않는': 'More than a',
  '생성형 AI 워크스페이스': 'generative AI workspace',
  '등록된 계정으로 이어서 작업합니다.': 'Sign in to pick up where you left off.',
  '비밀번호를 잊으셨나요?': 'Forgot your password?',
  '로그인으로 돌아가기': 'Back to sign in',
  '재설정 링크 받기': 'Send reset link',
  '새 비밀번호 설정': 'Set a new password',
  '비밀번호 재설정': 'Reset password',
  '가입한 이메일 주소로 재설정 링크를 보냅니다.': 'We will send a reset link to your sign-up address.',
  '비밀번호를 잊었다면 관리자에게 문의하세요.': 'If you forgot your password, ask your administrator.',
  '이메일 또는 비밀번호가 올바르지 않습니다.': 'That email or password is not right.',
  '로그인에 다섯 번 연속 실패해 잠시 잠겼습니다. 15분 뒤에 다시 시도하세요.': 'Five sign-ins in a row failed, so this address is locked for a while. Try again in 15 minutes.',
  '정지된 계정입니다. 관리자에게 문의하세요.': 'This account is suspended. Ask your administrator.',
  '이미 사용 중인 이메일입니다.': 'That email is already in use.',
  '지금은 회원가입을 받지 않습니다. 관리자에게 문의하세요.': 'Sign-ups are closed. Ask your administrator.',
  '서버에 연결하지 못했습니다. 잠시 후 다시 시도하세요.': 'Could not reach the server. Try again in a moment.',
  '요청을 처리하지 못했습니다. 잠시 후 다시 시도하세요.': 'Could not complete that. Try again in a moment.',
  '해당 주소로 가입된 계정이 있다면 재설정 링크를 보냈습니다. 30분 안에 사용하세요.': 'If an account exists for that address, a reset link is on its way. It expires in 30 minutes.',
  '링크가 만료되었습니다. 다시 요청하세요.': 'That link has expired. Request a new one.',
  '재설정 링크가 올바르지 않습니다. 다시 요청하세요.': 'That reset link is not valid. Request a new one.',
  '이미 사용한 링크입니다. 새 비밀번호로 로그인하거나 다시 요청하세요.': 'That link was already used. Sign in with the new password or request another.',
  '비밀번호를 바꿨습니다. 새 비밀번호로 로그인하세요.': 'Password changed. Sign in with the new one.',
  '비밀번호를 바꾸지 못했습니다. 링크를 다시 요청하세요.': 'Could not change the password. Request a new link.',
  '새 비밀번호를 정하면 바로 로그인됩니다. 다른 기기의 로그인은 모두 해제됩니다.': 'Setting a new password signs you in and signs out every other device.',
  '관리자 승인이 끝나면 크레딧이 배정되고 바로 쓸 수 있습니다.': 'Once an administrator approves you, credits are assigned and you can start.',
  '10자 이상, 숫자와 기호 포함': '10+ characters, with a number and a symbol',
  '홍길동': 'Your name',
  '검색 결과가 없습니다': 'No results',
  '아직 대화가 없습니다': 'No conversations yet',
  '자료와 지침을 프로젝트에 모아 두면, 모든 화면이 같은 맥락 위에서 작동합니다. 만든 아티팩트는 아티팩트 화면에 쌓이고 문서로 내보낼 수 있습니다.': 'Gather files and instructions into a project and every surface works from the same context. What you make is kept as artifacts and exports as documents.',
