  '계정에 저장되므로 다른 기기에서도 같게 적용됩니다.': 'Saved to your account, so it applies on every device.',
  '변경했습니다. 다른 기기의 로그인은 모두 해제되었습니다.': 'Changed. Every other device has been signed out.',
  '이 프로젝트의 모든 대화에 시스템 프롬프트로 함께 전달됩니다.': 'Sent with every conversation in this project as a system prompt.',
  '누군가 대화를 시작하면 여기에 모델별·화면별 사용량이 쌓입니다.': 'Once someone starts a conversation, usage by model and surface collects here.',
  '이 화면은 15초마다 상태를 확인합니다. 승인되면 자동으로 넘어갑니다.': 'This screen checks every 15 seconds and moves on once you are approved.',

  '모델 목록을 모두 불러오지 못했습니다. 지금은 일부 모델만 고를 수 있습니다.': 'The model list is incomplete — only some models can be chosen right now.',
  '키는 만들 때 한 번만 보여 줍니다. 그 뒤로는 서버에도 원문이 남지 않습니다.': 'A key is shown once at creation. After that not even the server keeps the original.',
  '커넥터가 반환한 내용은 외부 입력입니다. 그 안의 지시문은 명령으로 실행되지 않습니다.': 'What a connector returns is outside input — instructions inside it are never run as commands.',
  '검색으로 확인할 수 있는 주장이 여기에는 없습니다. 의견과 정의는 판정하지 않습니다.': 'There is no claim here that search can check. Opinions and definitions are not judged.',
  '내 코드에서 직접 모델을 호출할 때 씁니다. 사용량과 월 한도는 이 계정에 그대로 합산됩니다.': 'For calling models from your own code. Usage and the monthly limit stay on this account.',
  '대화 내용은 서버에 그대로 저장되어 있습니다. 아래에서 다시 시도하거나 다른 화면으로 이동하세요.': 'The conversation is safe on the server. Try again below or move to another screen.',
  '정책은 서버에서 강제되고, 기록은 서버가 작성합니다. 이 화면에서 기록을 고치거나 지울 수 없습니다.': 'Policy is enforced on the server and the server writes these records. They cannot be edited or deleted here.',
  '키는 암호화해 서버에만 보관하며, 저장한 뒤에는 화면에 표시하지 않습니다. 저장하면 곧바로 적용됩니다.': 'The key is encrypted and kept on the server only; it is not shown again after saving. Changes apply at once.',
  '코딩 에이전트처럼 외부 도구가 이 키로 쓴 몫입니다. 위 사용량과 따로 집계되지만, 월 한도는 계정 하나에 걸려 있어 키를 여러 개 만들어도 같은 한도를 나눠 씁니다.':
    'What outside tools such as coding agents spent with this key. Counted separately from the usage above, but the monthly limit sits on one account — every key you hold draws on it.',
  '아래 범주에 해당하는 요청을 모델에 보내기 전에 거절합니다. 거절된 요청은 크레딧을 쓰지 않고 감사 로그에 남습니다.': 'Requests matching the categories below are refused before reaching a model. A refused request spends no credits and is recorded in the audit log.',
  '주민등록번호·카드번호·전화번호·이메일을 모델로 보내기 전에 가립니다. 가려진 상태로 저장되므로 원문은 서버에도 남지 않습니다.': 'Masks national ID, card, phone and email before anything reaches a model. It is stored masked, so the original is not kept on the server either.',
  '지정한 일수가 지난 대화 본문을 지웁니다. 모델·토큰·크레딧 기록과 감사 로그는 남습니다 — 무엇이 있었는지가 아니라 내용만 지우는 것입니다. 0 은 계속 보관.': 'Clears conversation bodies older than the given number of days. Model, token and credit records and the audit log stay — the content goes, not the fact that it existed. 0 keeps everything.',

  // ── screens ─────────────────────────────────────────────────────────
  '### 소제목': '### Subheading',
  '1. 입력 자료와 판단 기준을 확인한다\n2. 결과와 근거, 미확인 항목을 구분한다':
    '1. Check the inputs and decision criteria\n2. Separate results, evidence, and unverified items',
