  '{date}에 {n} 크레딧으로 리필됩니다. 남은 크레딧은 이월되지 않습니다. 한도 변경은 관리자에게 문의하세요.':
    'Refills to {n} credits on {date}. Anything left does not carry over. Ask an administrator to change the limit.',
