  '사용법': 'How to use',
  '대화를 열면 첫 화면에 보입니다. 무엇을 가져와야 하는지, 한 턴에 무슨 일이 일어나는지.': 'Shown on the first screen of a conversation: what to bring, what a turn does.',
  '예: 논문 PDF 를 첨부하고 어느 학회 기준인지 알려 주세요. 리뷰어 관점에서 검토합니다.': 'e.g. Attach the paper PDF and name the venue. Reviewed from a reviewer’s seat.',
  '시작 문장': 'Conversation starters',
  '한 줄에 하나, 여섯 개까지. 첫 화면에 버튼으로 보이고 누르면 그대로 보냅니다.': 'One per line, up to six. Shown as buttons on the first screen; pressing one sends it as is.',
