  '이 대화': 'this conversation',
  '단축키 보기': 'shortcuts',
  '여기 적은 것은 모든 대화의 맨 앞에 들어갑니다. 에이전트나 프로젝트의 지침이 있으면 그쪽이 우선합니다.': 'What you write here goes at the front of every conversation. Agent or project instructions take precedence where they differ.',
  '나에 대해 알아 두면 좋은 것': 'What to know about me',
  '하는 일, 전공, 관심사, 자주 쓰는 도구 — 답을 맞추는 데 참고합니다. 대화에서만 쓰이고 보고서·슬라이드에는 들어가지 않습니다.': 'Your work, field, interests, the tools you use — for fitting answers to you. Used in conversations only, never in reports or slides.',
  '예: 직장에서 기획 업무를 맡고 있다. 전문 용어보다 쉬운 말이 좋고, 숫자는 표로 보여 주면 이해가 빠르다.': 'e.g. I work in planning at my company. Plain words over jargon, and numbers are easier for me in a table.',
  '답변 방식': 'How to respond',
  '말투, 길이, 형식, 언어 — 대화와 문서 모두에 적용됩니다.': 'Tone, length, format, language — applies to conversations and documents alike.',
  '예: 결론을 먼저, 짧게. 존댓말로. 어려운 말은 풀어서 설명해 주고, 잘 모르는 것은 모른다고 말해 주세요.': 'e.g. Conclusion first, keep it short. Explain difficult terms in plain words, and say so when you are not sure.',
  '저장했습니다. 다음 대화부터 적용됩니다.': 'Saved. Applies from the next conversation.',
  '가입 문의': 'Signup inquiry',
  '문의 주소': 'Contact address',
  '대기 화면의 「관리자에게 문의」가 여는 메일 주소입니다. 비우면 첫 관리자 계정의 주소를 씁니다.':
    'The address “Contact an administrator” on the waiting screen opens. Empty uses the first administrator account.',
  '입력한 설정을 저장한 뒤 내 주소로 한 통 보냅니다': 'Saves what is typed here, then sends one message to your own address',
  '재설정·가입 확인 메일에 담길 링크의 주소입니다. 사용자가 접속하는 주소를 넣으세요. 비어 있으면 메일은 나가도 링크를 만들 수 없습니다.':
    'The origin for links in reset and confirmation mails — the address people use. Empty means mail goes out but no link can be built.',
  '지금 이 화면을 연 주소를 넣습니다': 'Fills in the address this screen was opened from',
  '현재 주소 넣기': 'Use this address',
  '승인 후 사용': 'Approval required',
  '가입하면 대기 상태가 되고, 관리자가 승인하며 월 크레딧을 정합니다.': 'New accounts wait until an administrator approves them and sets a monthly allowance.',
  '바로 사용': 'Straight in',
  '가입 즉시 기본 월 크레딧으로 사용할 수 있습니다.': 'Accounts can be used right away with the default monthly allowance.',
  '받지 않음': 'Closed',
  '가입 화면이 요청을 거절합니다. 계정은 관리자만 만듭니다.': 'The signup form refuses requests. Only administrators create accounts.',
  '가입 방식': 'Signup mode',
  'SIGNUP_MODE 환경변수의 값입니다. 여기서 고르면 그 값을 덮어씁니다.': 'From the SIGNUP_MODE environment variable. Choosing here overrides it.',
  '가입 가능한 이메일 도메인': 'Email domains allowed to sign up',
  '쉼표로 구분합니다. 비우면 어떤 주소로도 가입할 수 있습니다. 하위 도메인은 따로 적어야 합니다.': 'Comma-separated. Empty allows any address. Subdomains must be listed separately.',
  '이메일 인증': 'Email verification',
  '가입한 주소로 확인 메일을 보냅니다': 'Send a confirmation mail to the address',
  '메일의 링크를 누른 뒤에야 가입한 것으로 칩니다. 승인 방식이면 그 뒤에 승인을 기다립니다.': 'The signup counts only after the link in the mail is clicked; with approval on, approval comes after that.',
  '메일 탭에 발송 서버가 설정되지 않아, 켜 두어도 확인 메일은 나가지 않고 인증 없이 가입됩니다.': 'No mail server is set on the Mail tab, so no confirmation is sent and signups go through unverified.',
  '바로 적용됩니다. 이미 가입한 계정에는 영향이 없습니다.': 'Applies immediately. Existing accounts are unaffected.',
  '회원 가입': 'Signup',
  '누가, 어떤 주소로 가입할 수 있는지, 주소를 메일로 확인할지 정합니다.': 'Who may sign up, from which addresses, and whether the address is confirmed by mail.',
  '가입하면 확인 메일이 갑니다. 메일의 링크를 누르면 가입이 끝납니다.': 'A confirmation mail follows signup. Clicking its link completes it.',
  '가입한 주소를 확인하는 중…': 'Confirming your address…',
  '주소를 확인했습니다. 로그인하세요.': 'Address confirmed. Sign in.',
  '주소를 확인했습니다. 관리자가 승인하면 쓸 수 있습니다. 로그인하면 진행 상황이 보입니다.': 'Address confirmed. You can start once an administrator approves; sign in to see where it stands.',
  '주소를 확인하지 못했습니다. 로그인해서 확인 메일을 다시 받으세요.': 'Could not confirm the address. Sign in to have the mail sent again.',
  '가입 가능한 주소': 'Accepted addresses',
  '메일의 링크를 눌러 주소를 확인해 주세요': 'Confirm your address from the mail we sent',
  '가입한 주소로 확인 메일을 보냈습니다. 메일의 링크를 누르면 가입이 끝납니다. 메일이 보이지 않으면 스팸함을 확인하거나 다시 보내세요.': 'A confirmation mail went to your address. Clicking its link completes the signup. If it is missing, check spam or send it again.',
  '주소 확인 대기': 'Awaiting confirmation',
