  '하려는 일을 고르면 필요한 자료와 아티팩트의 모양까지 함께 준비됩니다.':
    'Pick the job and the material it needs — and the shape it comes in — are set with it.',
  '어떤 모양으로 받을까요?': 'What shape should it come in?',
  '모델 목록을 다시 읽지 못했습니다.': 'Could not reload the model list.',
  '모델 목록을 다시 읽었습니다 · 모델 {n}종': 'Model list reloaded · {n} models',
  '모델 목록 새로고침': 'Refresh model list',
  '파일을 내려받지 못했습니다.': 'Could not download the file.',
  '{name} 수정': 'Edit {name}',
  '작업을 취소하지 못했습니다.': 'Could not cancel the job.',
  '목소리': 'Voice',
  '그림': 'Picture',
  '그림 바꾸기': 'Replace the picture',
  '그림 모델로 바꾸기': 'Replace with a drawn picture',
  '이 장의 도식은 글에서 자동으로 그린 것입니다. 이미지 모델의 그림으로 바꾸면 도식은 사라집니다.': 'This slide’s figure was drawn from its words. A picture from the image model replaces it.',
  '이 장': 'this slide',
  '아티팩트 검색': 'Search artifacts',
  '찾는 아티팩트가 없습니다': 'Nothing matches',
  '제목의 다른 부분으로 찾아보세요.': 'Try another part of the title.',
  '구성 단계 모델': 'Planning model',
  '보고서·슬라이드의 구성을 이 모델이 잡고, 쓰는 동안 자료의 수치 읽기·계산·검사 같은 판정도 이 모델이 맡습니다. 본문은 언제나 화면의 모델이 씁니다. 판정 호출은 짧아서 여기만 다른 모델로 두어도 비용은 거의 그대로입니다.':
    'This model plans reports and decks, and while they are written it also does the judging: reading figures from the material, calculations and checks. The body is always written by the surface’s model. Judging calls are short, so another model here costs almost nothing extra.',
  '구성에 쓸 모델': 'Model that plans',
  '비워 두면 각 화면이 쓰는 모델이 구성과 판정까지 맡습니다. 개인정보 때문에 strict-local 로 보낸 대화에서는 이 모델의 strict-local 판이 맡고, 그런 판이 없거나 본문 모델보다 데이터 경계가 넓으면 본문 모델이 맡습니다.':
    'Left empty, each surface plans and judges with its own model. A turn privacy routed to strict-local uses this model’s strict-local entry; without one, or when its data boundary is wider than the writer’s, the writer does it.',
  '화면의 모델을 그대로 사용': 'Use the surface’s own model',
  '저장했습니다': 'Saved',
  '그림을 넣지 못했습니다.': 'Could not add the picture.',
  '그림 넣기': 'Add a picture',
  '아직 만든 그림이 없습니다. 이미지 화면에서 만들면 여기에 나타납니다.':
    'No pictures yet. Anything you make on the image surface appears here.',
  '이미지 화면이 꺼져 있어 넣을 그림을 만들 수 없습니다. 관리자가 설정에서 켤 수 있습니다.':
    'The image surface is switched off, so there is nothing to put here yet. An administrator can turn it on in the system settings.',
